import Quiz from '../models/Quiz.js';
import QuizAttempt from '../models/QuizAttempt.js';
import Enrollment from '../models/Enrollment.js';
import Progress from '../models/Progress.js';
import Course from '../models/Course.js';
import UploadedDocument from '../models/UploadedDocument.js';
import { generateQuizQuestionsWithAI, sanitizeQuizQuestion } from '../services/geminiService.js';

export const getQuizzes = async (req, res, next) => {
  try {
    // Return standard catalog quizzes AND custom quizzes generated by this user
    const quizzes = await Quiz.find({
      $or: [
        { isCustom: false },
        { isCustom: { $exists: false } },
        { createdBy: req.user._id },
      ],
    })
      .populate('course', 'title code category thumbnail instructor')
      .sort({ createdAt: -1 });

    const attempts = await QuizAttempt.find({ user: req.user._id }).sort({
      createdAt: -1,
    });

    const formattedQuizzes = quizzes.map((quiz) => {
      const quizAttempts = attempts.filter(
        (att) => att.quiz && att.quiz.toString() === quiz._id.toString()
      );
      const bestAttempt =
        quizAttempts.length > 0
          ? quizAttempts.reduce((best, curr) =>
              curr.percentage > best.percentage ? curr : best
            )
          : null;
      const latestAttempt = quizAttempts[0] || null;

      return {
        _id: quiz._id,
        title: quiz.title,
        description: quiz.description,
        durationMinutes: quiz.durationMinutes,
        passingPercentage: quiz.passingPercentage,
        totalQuestions: quiz.questions.length,
        course: quiz.course || null,
        isCustom: Boolean(quiz.isCustom),
        topic: quiz.topic || '',
        difficulty: quiz.difficulty || 'Medium',
        questionType: quiz.questionType || 'MCQ',
        attemptsCount: quizAttempts.length,
        bestScore: bestAttempt ? bestAttempt.score : null,
        bestPercentage: bestAttempt ? bestAttempt.percentage : null,
        latestAttempt: latestAttempt
          ? {
              _id: latestAttempt._id,
              score: latestAttempt.score,
              totalQuestions: latestAttempt.totalQuestions,
              percentage: latestAttempt.percentage,
              passed: latestAttempt.passed,
              createdAt: latestAttempt.createdAt,
            }
          : null,
      };
    });

    res.status(200).json({
      success: true,
      count: formattedQuizzes.length,
      quizzes: formattedQuizzes,
    });
  } catch (error) {
    next(error);
  }
};

export const getQuizById = async (req, res, next) => {
  try {
    const quiz = await Quiz.findById(req.params.id).populate(
      'course',
      'title code category instructor'
    );

    if (!quiz) {
      return res.status(404).json({
        success: false,
        message: 'Quiz not found.',
      });
    }

    // Security requirement: Never expose correctOptionIndex or explanation before submission!
    const sanitizedQuestions = quiz.questions.map((q, index) => {
      const sanitized = sanitizeQuizQuestion(q);
      return {
        _id: q._id,
        number: index + 1,
        questionText: sanitized.questionText,
        options: sanitized.options,
      };
    });

    res.status(200).json({
      success: true,
      quiz: {
        _id: quiz._id,
        title: quiz.title,
        description: quiz.description,
        durationMinutes: quiz.durationMinutes,
        passingPercentage: quiz.passingPercentage,
        totalQuestions: sanitizedQuestions.length,
        course: quiz.course || null,
        isCustom: Boolean(quiz.isCustom),
        topic: quiz.topic || '',
        difficulty: quiz.difficulty || 'Medium',
        questionType: quiz.questionType || 'MCQ',
        questions: sanitizedQuestions,
      },
    });
  } catch (error) {
    next(error);
  }
};

export const generateCustomQuiz = async (req, res, next) => {
  try {
    const {
      topic = 'Computer Science Fundamentals',
      sourceText = '',
      documentId = null,
      courseId = null,
      numQuestions = 5,
      difficulty = 'Medium',
      questionType = 'MCQ',
      durationMinutes = 15,
      imageData = null,
    } = req.body;

    let contentToUse = sourceText || '';
    let docName = '';

    if (documentId) {
      const doc = await UploadedDocument.findOne({ _id: documentId, user: req.user._id });
      if (doc) {
        contentToUse = doc.extractedText;
        docName = doc.originalName;
      }
    }

    if (!topic && !contentToUse && !imageData) {
      return res.status(400).json({
        success: false,
        message: 'Please provide a topic, paste study text, or upload a document to generate a quiz.',
      });
    }

    const questionCountNum = Math.min(20, Math.max(3, Number(numQuestions) || 5));

    // Call Gemini API to construct questions
    const generatedQuestions = await generateQuizQuestionsWithAI({
      topic: topic.trim(),
      sourceText: contentToUse,
      imageData,
      numQuestions: questionCountNum,
      difficulty,
      questionType,
    });

    let assignedCourse = null;
    if (courseId) {
      assignedCourse = await Course.findById(courseId);
    }
    if (!assignedCourse) {
      // Pick first available course or null
      assignedCourse = await Course.findOne();
    }

    const quizTitle = `AI Quiz: ${topic.trim().slice(0, 40)}${docName ? ` (${docName})` : ''}`;
    const quizDesc = `Custom ${difficulty} ${questionType} assessment generated by LearnSpace AI Tutor on ${topic.trim()}.`;

    const newQuiz = await Quiz.create({
      title: quizTitle,
      description: quizDesc,
      course: assignedCourse ? assignedCourse._id : null,
      isCustom: true,
      createdBy: req.user._id,
      topic: topic.trim(),
      difficulty,
      questionType,
      durationMinutes: Number(durationMinutes) || 15,
      passingPercentage: 60,
      questions: generatedQuestions,
    });

    await Progress.create({
      user: req.user._id,
      actionType: 'custom_quiz_generated',
      title: `Generated custom AI quiz: "${quizTitle}"`,
      details: `${questionCountNum} ${difficulty} questions on ${topic.trim()}`,
      metadata: { quizId: newQuiz._id },
    });

    // Return sanitized questions without answers
    const sanitized = newQuiz.questions.map((q, idx) => ({
      _id: q._id,
      number: idx + 1,
      questionText: q.questionText,
      options: q.options,
    }));

    res.status(201).json({
      success: true,
      message: 'AI Quiz generated successfully!',
      quiz: {
        _id: newQuiz._id,
        title: newQuiz.title,
        description: newQuiz.description,
        durationMinutes: newQuiz.durationMinutes,
        passingPercentage: newQuiz.passingPercentage,
        totalQuestions: sanitized.length,
        course: assignedCourse ? { _id: assignedCourse._id, title: assignedCourse.title } : null,
        isCustom: true,
        topic: newQuiz.topic,
        difficulty: newQuiz.difficulty,
        questionType: newQuiz.questionType,
        questions: sanitized,
      },
    });
  } catch (error) {
    next(error);
  }
};

export const submitQuiz = async (req, res, next) => {
  try {
    const { answers, timeSpentSeconds = 0 } = req.body;

    const quiz = await Quiz.findById(req.params.id).populate('course', 'title code');
    if (!quiz) {
      return res.status(404).json({
        success: false,
        message: 'Quiz not found.',
      });
    }

    if (!answers || typeof answers !== 'object') {
      return res.status(400).json({
        success: false,
        message: 'Please provide your quiz answers before submitting.',
      });
    }

    let score = 0;
    const evaluatedAnswers = [];
    const detailedReview = [];

    quiz.questions.forEach((question, index) => {
      const qId = question._id.toString();
      let selectedOptionIndex = -1;

      if (Array.isArray(answers)) {
        const found = answers.find(
          (a) => a.questionId === qId || a.questionIndex === index
        );
        if (found !== undefined && typeof found.selectedOptionIndex === 'number') {
          selectedOptionIndex = found.selectedOptionIndex;
        }
      } else if (typeof answers[qId] === 'number') {
        selectedOptionIndex = answers[qId];
      } else if (typeof answers[index] === 'number') {
        selectedOptionIndex = answers[index];
      }

      const isCorrect = selectedOptionIndex === question.correctOptionIndex;
      if (isCorrect) {
        score += 1;
      }

      evaluatedAnswers.push({
        questionId: question._id,
        selectedOptionIndex,
        correctOptionIndex: question.correctOptionIndex,
        isCorrect,
      });

      const sanitized = sanitizeQuizQuestion(question);
      detailedReview.push({
        questionId: question._id,
        number: index + 1,
        questionText: sanitized.questionText,
        options: sanitized.options,
        selectedOptionIndex,
        correctOptionIndex: question.correctOptionIndex,
        isCorrect,
        explanation: sanitized.explanation || question.explanation,
      });
    });

    const totalQuestions = quiz.questions.length;
    const percentage = Math.round((score / totalQuestions) * 100);
    const passed = percentage >= quiz.passingPercentage;

    const attempt = await QuizAttempt.create({
      user: req.user._id,
      quiz: quiz._id,
      course: quiz.course ? quiz.course._id : null,
      answers: evaluatedAnswers,
      score,
      totalQuestions,
      percentage,
      passed,
      timeSpentSeconds: Number(timeSpentSeconds) || 0,
    });

    // Ensure student is enrolled in the course if associated
    if (quiz.course && quiz.course._id) {
      const existingEnrollment = await Enrollment.findOne({
        user: req.user._id,
        course: quiz.course._id,
      });
      if (!existingEnrollment) {
        await Enrollment.create({
          user: req.user._id,
          course: quiz.course._id,
          completedLessons: [],
          progressPercentage: 0,
          completed: false,
        });
      }
    }

    await Progress.create({
      user: req.user._id,
      course: quiz.course ? quiz.course._id : null,
      actionType: 'quiz_completed',
      title: `Completed ${quiz.title}`,
      details: `Scored ${score}/${totalQuestions} (${percentage}%) - ${
        passed ? 'Passed' : 'Needs Review'
      }.`,
      metadata: {
        score,
        percentage,
        quizId: quiz._id,
      },
    });

    res.status(201).json({
      success: true,
      message: passed
        ? `Congratulations! You passed with ${percentage}% (${score}/${totalQuestions}).`
        : `Quiz submitted! You scored ${percentage}% (${score}/${totalQuestions}). Review the explanations below to improve.`,
      result: {
        attemptId: attempt._id,
        quizId: quiz._id,
        quizTitle: quiz.title,
        courseTitle: quiz.course ? quiz.course.title : 'Custom AI Assessment',
        score,
        totalQuestions,
        percentage,
        passingPercentage: quiz.passingPercentage,
        passed,
        timeSpentSeconds: attempt.timeSpentSeconds,
        submittedAt: attempt.createdAt,
        review: detailedReview,
      },
    });
  } catch (error) {
    next(error);
  }
};
